// app/Sources/GraphicPane+Source.swift — the Graphic sub-tab's Source
// section (road map 10 §5j, G5a): which module draws the clip, the three
// buttons (Open in Editor, Reveal in Finder, Duplicate as New Graphic…), and
// what the module says about the clip, each group under its own heading
// (#221): "Compiling the module" over its compile (an error, or what its top
// level warned), when there is any; the clip's FIRST frame drawn and
// rasterized at the clip's own size, when one was drawn, so a missing font
// or a size mismatch shows here (G3c's owed warning, road map 10 §10.6); and
// "In the graphics folder" over what the folder's scan skipped or could not
// watch, each with Reveal (G-24 (b)).
//
// **The report is the paused frame's own two calls** — `module.svg` then
// `library.rasterize` at `graphic.width × height`
// (`LayerRenderersGraphic.swift`) — memoised by module, revision, library,
// the recipe's frame hash and the size, so a miss costs one paused frame.
// While a live gesture runs nothing is recomputed: a miss answers the
// clip's last report.

import AppKit

/// What a graphic clip's module says about it: its compile's diagnostics,
/// and the first frame's — drawn at the graphic's `frame`.
struct GraphicClipReport: Equatable {
    let compile: [GraphicDiagnostic]
    let render: [GraphicDiagnostic]
    let frame: Int?

    static let empty = GraphicClipReport(compile: [], render: [], frame: nil)
}

extension GraphicPane {
    /// The module, its file and revision, the three buttons and the
    /// diagnostics. With clips of different modules, a note naming them.
    func sourceSection() -> InspectorSection {
        guard let first = shared() else {
            let names = Set(binding.graphicClips.compactMap { $0.graphic?.name }).sorted()
            let listed = names.joined(separator: ", ")
            return InspectorSection(
                id: "graphic.source", title: "Source", summary: { "\(names.count) modules" },
                defaultExpanded: false,
                rows: [
                    InspectorNoteLabel { "Drawn by different modules: \(listed)" },
                    InspectorNoteLabel { "Select one module's clips to edit its properties." },
                ])
        }
        let current = { [weak self] in self?.shared() }
        func metaName() -> String {
            if case .compiled(_, _, let meta, _)? = current()?.entry,
               let name = meta["name"] as? String, !name.isEmpty
            {
                return name
            }
            return current()?.name ?? first.name
        }
        func revision() -> String {
            guard let file = current()?.file else { return "missing" }
            return String(file.revision.prefix(8))
        }
        let open: () -> Void = { [weak self] in self?.openFile() }
        let hasFile = { current()?.file != nil }
        let duplicate = OptionButtonControl(
            title: "Duplicate as New Graphic…",
            action: { [weak self] in
                guard let self, let shared = current(), let file = shared.file else {
                    return NSSound.beep()
                }
                self.duplicateAsNewGraphic(file, schema: self.schema(shared)?.raw)
            },
            enabled: hasFile, onEdit: {})
        var rows: [NSView] = [
            inspectorRow("Name", [inspectorReadout(width: 170) { metaName() }]),
            inspectorRow("File", [inspectorReadout(width: 170) { "\(first.name).js" }]),
            inspectorRow("Revision", [inspectorReadout(width: 170) { revision() }]),
            inspectorButtonRow([
                OptionButtonControl(
                    title: "Open in Editor", action: open, enabled: hasFile, onEdit: {}),
                OptionButtonControl(
                    title: "Reveal in Finder",
                    action: {
                        guard let url = current()?.file?.url else { return NSSound.beep() }
                        NSWorkspace.shared.activateFileViewerSelecting([url])
                    },
                    enabled: hasFile, onEdit: {}),
            ]),
            inspectorButtonRow([duplicate]),
        ]
        var report = GraphicClipReport.empty
        if let clip = binding.graphicClips.first, let document = binding.document {
            let version = GraphicRegistry.shared.snapshot(for: document.recipeKey)?.libraryVersion
            report = self.report(for: clip, first, libraryVersion: version ?? "")
        }
        let diagnostics = report.compile + report.render
        if !report.compile.isEmpty {
            rows.append(InspectorNoteLabel { "Compiling the module" })
            rows += report.compile.map { GraphicDiagnosticRow($0, onOpen: open) }
        }
        if report.frame != nil {
            let checked = report.render.isEmpty
                ? "No errors or warnings at the clip's first frame"
                : "Checked at the clip's first frame"
            rows.append(InspectorNoteLabel { checked })
            rows += report.render.map { GraphicDiagnosticRow($0, onOpen: open) }
        }
        let folder = folderWarnings()
        if !folder.isEmpty {
            let reveal: () -> Void = { [weak self] in
                guard let url = self?.binding.document?.graphicStore?.folderURL,
                      FileManager.default.fileExists(atPath: url.path)
                else { return NSSound.beep() }
                NSWorkspace.shared.activateFileViewerSelecting([url])
            }
            rows.append(InspectorNoteLabel { "In the graphics folder" })
            rows += folder.map {
                GraphicDiagnosticRow(
                    GraphicDiagnostic(
                        level: "warning", message: $0, line: nil, column: nil, frame: nil),
                    openTitle: "Reveal", help: "Reveal the graphics folder in Finder",
                    onOpen: reveal)
            }
        }
        let errors = diagnostics.filter { $0.level == "error" }.count
        let warnings = diagnostics.count - errors + folder.count
        return InspectorSection(
            id: "graphic.source", title: "Source",
            summary: {
                errors > 0 ? (errors == 1 ? "1 error" : "\(errors) errors")
                    : warnings > 0 ? (warnings == 1 ? "1 warning" : "\(warnings) warnings")
                    : metaName()
            },
            defaultExpanded: false,
            rows: rows)
    }

    /// Opens the shared module's file in the app the system gives `.js`.
    func openFile() {
        guard let url = shared()?.file?.url else { return NSSound.beep() }
        NSWorkspace.shared.open(url)
    }

    /// The module's compile, and `clip`'s first frame drawn and rasterized at
    /// the clip's own size — through the memo, and never recomputed while a
    /// live gesture runs.
    func report(
        for clip: ClipSnapshot, _ shared: Shared, libraryVersion: String
    ) -> GraphicClipReport {
        let module: GraphicModule, revision: String
        switch shared.entry {
        case nil:
            return GraphicClipReport(
                compile: [GraphicDiagnostic.noModule(shared.name)],
                render: [], frame: nil)
        case .failed(let diagnostics, _)?:
            return GraphicClipReport(compile: diagnostics, render: [], frame: nil)
        case .compiled(let compiled, let hash, _, _)?:
            module = compiled
            revision = hash
        }
        guard let graphic = clip.graphic, let document = binding.document else { return .empty }
        if document.isLiveEditing { return lastReports[clip.id] ?? .empty }
        guard let set = GraphicRegistry.shared.snapshot(for: document.recipeKey),
              let source = layerSource(of: clip),
              case .graphic(_, let hash, let frame, let propsJSON, let ctxJSON) = source
        else { return .empty }
        let key = [
            shared.name, revision, libraryVersion, hash, "\(graphic.width)×\(graphic.height)",
        ].joined(separator: "|")
        if let hit = reportMemo[key] {
            lastReports[clip.id] = hit
            return hit
        }
        var render: [GraphicDiagnostic] = []
        do {
            let drawn = try module.svg(
                frame: frame, propsJSON: propsJSON, ctxJSON: ctxJSON,
                budgetMs: GraphicRegistry.previewBudgetMs)
            render += drawn.warnings
            do {
                let raster = try set.library.rasterize(
                    drawn.svg, width: graphic.width, height: graphic.height)
                render += raster.warnings
            } catch {
                render += GraphicDiagnostic.of(error)
            }
        } catch {
            render += GraphicDiagnostic.of(error)
        }
        let report = GraphicClipReport(
            compile: module.compileWarnings, render: render, frame: frame)
        if reportMemo.count >= 64 { reportMemo.removeAll() }
        reportMemo[key] = report
        lastReports[clip.id] = report
        return report
    }

    /// `clip`'s layer source in the recipe at its start, through
    /// `layerMemo`: `recipe(at:)` is asked only on a miss, and the memo is
    /// emptied when the binding's project is another handle.
    func layerSource(of clip: ClipSnapshot) -> RecipeSourceRef? {
        guard let project = binding.project else { return nil }
        if project !== layerProject {
            layerMemo = [:]
            layerProject = project
        }
        if let hit = layerMemo[clip.id] { return hit }
        guard let layer = project.recipe(at: clip.start)?.layers
            .first(where: { $0.clip == clip.id })
        else { return nil }
        layerMemo[clip.id] = layer.source
        return layer.source
    }

    /// Copies the module's file under a new name the person types, then
    /// repoints the selected clips at it with `set_graphic {name}` — the
    /// copy is not undoable (G-3), the repoint is one step. The MCP mirror is
    /// `write_graphic` of the source under the new name, then `set_graphic`.
    func duplicateAsNewGraphic(_ file: GraphicModuleFile, schema: [String: Any]?) {
        guard let store = binding.document?.graphicStore else { return NSSound.beep() }
        let suggestion = store.uniqueModuleName(file.name + "-copy")
        let alert = NSAlert()
        alert.alertStyle = .informational
        alert.messageText = "Duplicate \(file.name).js as a new graphic"
        alert.informativeText =
            "The copy is written into the package's graphics/ folder and the selected clips "
            + "are drawn by it. Writing the file cannot be undone; switching the clips can."
        let field = NSTextField(string: suggestion)
        field.frame = NSRect(x: 0, y: 0, width: 240, height: 24)
        field.placeholderString = "Module name"
        alert.accessoryView = field
        alert.addButton(withTitle: "Duplicate")
        alert.addButton(withTitle: "Cancel")
        alert.window.initialFirstResponder = field
        guard alert.runModal() == .alertFirstButtonReturn else { return }
        let name = field.stringValue.trimmingCharacters(in: .whitespaces)
        func refuse(_ sentence: String) {
            NSAlert(error: NSError(
                domain: "FrameJob", code: 1, userInfo: [NSLocalizedDescriptionKey: sentence]))
                .runModal()
        }
        guard GraphicStore.isModuleName(name) else { return refuse(GraphicStore.nameSentence(name)) }
        guard !store.holdsModule(named: name) else {
            return refuse("graphics/\(name).js already exists")
        }
        do {
            try store.write(name: name, source: String(decoding: file.bytes, as: UTF8.self))
        } catch {
            return refuse("graphics/\(name).js could not be written: \(error.localizedDescription)")
        }
        store.rescan()
        let clips = binding.graphicClips.map(\.id)
        binding.apply(
            "Duplicate Graphic",
            clips.isEmpty ? [] : [.setGraphicRaw(clips: clips, patch: ["name": name], schema: schema)])
    }
}

/// One diagnostic: "line L, column C — message", an error in the strong
/// ink and a warning in the muted one. A click on it, or on its Open, opens
/// the module in the editor; a folder row's button is Reveal instead.
final class GraphicDiagnosticRow: NSView {
    let diagnostic: GraphicDiagnostic
    private let onOpen: () -> Void
    let label = NSTextField(wrappingLabelWithString: "")

    init(
        _ d: GraphicDiagnostic, openTitle: String = "Open",
        help: String = "Open the module in the editor", onOpen: @escaping () -> Void
    ) {
        diagnostic = d
        self.onOpen = onOpen
        super.init(frame: .zero)
        var place = ""
        if let line = d.line {
            place = d.column.map { "line \(line), column \($0) — " } ?? "line \(line) — "
        }
        label.stringValue = place + d.message
        label.font = DS.sans(11)
        label.textColor = d.level == "error" ? DS.textStrong : DS.textMuted
        label.isSelectable = false
        label.preferredMaxLayoutWidth = 200
        label.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        let open = OptionButtonControl(
            title: openTitle, action: { [weak self] in self?.onOpen() }, enabled: { true },
            onEdit: {})
        open.setContentHuggingPriority(.required, for: .horizontal)
        let row = NSStackView(views: [label, open])
        row.orientation = .horizontal
        row.alignment = .top
        row.spacing = 6
        row.translatesAutoresizingMaskIntoConstraints = false
        addSubview(row)
        NSLayoutConstraint.activate([
            row.topAnchor.constraint(equalTo: topAnchor),
            row.bottomAnchor.constraint(equalTo: bottomAnchor),
            row.leadingAnchor.constraint(
                equalTo: leadingAnchor, constant: InspectorMetrics.markGutter),
            row.trailingAnchor.constraint(equalTo: trailingAnchor),
        ])
        toolTip = help
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("GraphicDiagnosticRow does not support NSCoder")
    }

    override func mouseDown(with event: NSEvent) {
        onOpen()
    }
}
// app/Sources/GraphicPane.swift — the Clip tab's GRAPHIC sections (road map
// 10 §5j, G5a): Source (in `GraphicPane+Source.swift`), Properties from the
// module's schema (rows from `GraphicSchemaRows.swift`), Size and Timeline.
// With no action selected every write is `set_graphic`. With one selected, a
// Properties write — Reset's included — goes to the action's END with the
// module's current schema, one `set_action_end` naming `graphic.props.<key>`,
// except an `animate: false` prop's, which stays the clip's (spec §11 G-34
// (l), G-41 (d), G-42 (d)); Size and
// Timeline still write `set_graphic`, so their rows are ⊘. The core
// validates both.
//
// **Never shown itself**: like `ShapePane`, a factory `ClipPane` holds and
// calls when EVERY selected clip is a graphic clip.
//
// **Several graphic clips.** Source and Size always; Properties only when
// every clip is drawn by ONE module (one schema to build rows from, and the
// schema `set_graphic` needs), and Timeline only for one clip — its `in`
// and `length` are that clip's own. With different modules Source says so
// and names them (spec §11 G-15).
//
// **The schema is the registry's** (`GraphicRegistry.entry(named:for:)`,
// main only), the same read `AgentServer+Graphics.compiledModule` makes for
// the tool path. Nothing here rescans the store from an observer: `drain()`
// is not re-entrant (road map 10 §10.6 G3a).

import AppKit

extension InspectorBinding {
    /// The selected clips drawn by a module.
    var graphicClips: [ClipSnapshot] {
        clips.filter { clip in
            if case .graphic = clip.source { return clip.graphic != nil }
            return false
        }
    }
}

final class GraphicPane: InspectorPaneView {
    /// The report of each module/revision/library/frame hash/size seen, and
    /// the last report per clip — what a miss answers while a live gesture
    /// runs, so the signature holds still through a drag.
    var reportMemo: [String: GraphicClipReport] = [:]
    var lastReports: [UInt32: GraphicClipReport] = [:]
    /// The parsed schema of the last module asked, keyed "name|revision".
    var schemaMemo: (key: String, schema: GraphicSchema)?
    /// Each clip's recipe layer source under `layerProject`, the handle it
    /// was read from; emptied when the binding's project is another handle.
    weak var layerProject: ReelProject?
    var layerMemo: [UInt32: RecipeSourceRef] = [:]

    /// Whether the graphic sections apply: they write `set_graphic`, which
    /// errors on any other kind, so a mixed selection gets none of them.
    var allGraphic: Bool {
        !binding.clips.isEmpty && binding.graphicClips.count == binding.clips.count
    }

    /// The one module every selected graphic clip is drawn by.
    struct Shared {
        let name: String
        let file: GraphicModuleFile?
        let entry: GraphicRegistry.Entry?
    }

    /// nil when the selection's modules differ (or it holds no graphic).
    func shared() -> Shared? {
        let names = Set(binding.graphicClips.compactMap { $0.graphic?.name })
        guard names.count == 1, let name = names.first else { return nil }
        let document = binding.document
        return Shared(
            name: name, file: document?.graphicStore?.module(named: name),
            entry: document.flatMap {
                GraphicRegistry.shared.entry(named: name, for: $0.recipeKey)
            })
    }

    /// The compiled schema of `shared`, parsed in the module's order, and
    /// the registry's dictionary the ops carry. Parsed once per name and
    /// revision (`schemaMemo`).
    func schema(_ shared: Shared?) -> (schema: GraphicSchema, raw: [String: Any])? {
        guard let shared, case .compiled(let module, let revision, _, let raw)? = shared.entry
        else { return nil }
        let key = "\(shared.name)|\(revision)"
        if let memo = schemaMemo, memo.key == key { return (memo.schema, raw) }
        let parsed = GraphicSchema(describeJSON: module.describeJSON(), schema: raw)
        schemaMemo = (key, parsed)
        return (parsed, raw)
    }

    /// The selection's stored props, merged; the first clip holding a key wins.
    func storedProps() -> [String: GraphicPropValue] {
        var merged: [String: GraphicPropValue] = [:]
        for clip in binding.graphicClips {
            merged.merge(clip.graphic?.props ?? [:]) { first, _ in first }
        }
        return merged
    }

    /// The selected action's end props (G-34 (a)); none with no action
    /// selected. Its keys the schema lacks are the action's stale rows.
    func endProps() -> [String: GraphicPropValue] {
        binding.selectedAction?.end.graphic?.props ?? [:]
    }

    /// The asset folder's file names, sorted.
    func assetNames() -> [String] {
        (binding.document?.graphicStore?.scan.assets.map(\.name) ?? []).sorted()
    }

    /// What the graphics folder's scan skipped or could not watch, in its own
    /// sentences — the Source section's folder rows (G-24 (b)).
    func folderWarnings() -> [String] {
        binding.document?.graphicStore?.scan.warnings ?? []
    }

    /// The schema's entries whole (a default, bounds or options a row is
    /// built from), the stale keys (the clip's, then the selected action's
    /// end's, `actionStaleKeys`, a declared key no action may animate
    /// included, G-41), each asset popup's names (the selected end's
    /// included, G-42), the
    /// diagnostics' messages and the folder's warnings. Stored values, the
    /// revision and the playhead are NOT here: they are read fresh by
    /// `refresh()`.
    override var structureSignature: String {
        guard allGraphic else { return super.structureSignature + "|-" }
        let shared = self.shared()
        let parsed = schema(shared)
        let keys = parsed?.schema.entries.map { String(describing: $0) } ?? []
        let stale = GraphicSchemaRows.staleKeys(stored: storedProps(), schema: parsed?.schema)
        var messages = ["-", "-"]
        if let shared, let clip = binding.graphicClips.first, let document = binding.document {
            let version = GraphicRegistry.shared.snapshot(for: document.recipeKey)?.libraryVersion
            let report = self.report(for: clip, shared, libraryVersion: version ?? "")
            func spell(_ list: [GraphicDiagnostic]) -> String {
                list.map { "\($0.level):\($0.line ?? -1):\($0.column ?? -1):\($0.message)" }
                    .joined(separator: "¶")
            }
            messages = [spell(report.compile), spell(report.render)]
        }
        messages.append(folderWarnings().joined(separator: "¶"))
        return [
            super.structureSignature, shared?.name ?? "mixed", keys.joined(separator: ","),
            stale.joined(separator: ","), assetSignature(parsed?.schema),
            GraphicSchemaRows.actionStaleKeys(end: endProps(), schema: parsed?.schema)
                .joined(separator: ","),
        ].joined(separator: "|") + "|" + messages.joined(separator: "|")
    }

    /// Each asset entry's popup names, from the rows' own
    /// `GraphicSchemaRows.assetNames` call, the selected action's end's names
    /// counting (G-42 (d)): names joined by ",", entries by ";".
    private func assetSignature(_ schema: GraphicSchema?) -> String {
        let files = assetNames(), clips = binding.graphicClips
        return (schema?.entries ?? []).filter { $0.type == "asset" }.map {
            GraphicSchemaRows.assetNames(for: $0, files: files, clips: clips, end: endProps())
                .joined(separator: ",")
        }.joined(separator: ";")
    }

    // MARK: - Properties

    /// One row per schema key in the module's order, then the stale keys,
    /// sorted, then — with an action selected — the end's own stale keys
    /// (G-34 (l), O2), a declared key whose entry is not `animatable` among
    /// them (G-41 (c)). With no compiled schema every stored key is stale.
    /// Reset nulls every stored key; with an action selected it writes each
    /// declared default through the rows' own split, into the END (an
    /// asset's `null` as `""`, G-42 (d)), an `animate: false` prop's (G-41
    /// (d)) onto the clip (O7). Its `differs` folds from the rows.
    func propertiesSection() -> InspectorSection {
        let binding = self.binding
        let shared = self.shared()
        let parsed = schema(shared)
        let clips = { binding.graphicClips }
        let assets = { [weak self] in self?.assetNames() ?? [] }
        var rows: [NSView] = parsed?.schema.entries.map {
            GraphicSchemaRows.row(
                $0, binding, clips: clips, schema: parsed?.raw ?? [:], assets: assets)
        } ?? []
        let stored = storedProps()
        for key in GraphicSchemaRows.staleKeys(stored: stored, schema: parsed?.schema) {
            rows.append(
                GraphicSchemaRows.staleRow(
                    key: key, value: stored[key] ?? .null, binding, clips: clips))
        }
        let ends = endProps()
        let declared = Set(parsed?.schema.keys ?? [])
        for key in GraphicSchemaRows.actionStaleKeys(end: ends, schema: parsed?.schema) {
            rows.append(
                GraphicSchemaRows.actionStaleRow(
                    key: key, value: ends[key] ?? .null, declared: declared.contains(key), binding))
        }
        let note: String?
        if parsed == nil {
            note = "The module did not compile — see Source. Stored values are listed below."
        } else if parsed?.schema.entries.isEmpty == true {
            note = "The module declares no properties."
        } else {
            note = nil
        }
        let count = parsed?.schema.entries.count ?? 0
        return InspectorSection(
            id: "graphic.properties", title: "Properties",
            summary: { count == 1 ? "1 property" : "\(count) properties" },
            note: note.map { text -> () -> String? in { text } },
            reset: {
                if binding.selectedAction != nil {
                    let entries = parsed?.schema.entries ?? []
                    let defaults = Dictionary(
                        entries.map { ($0.key, $0.default) }, uniquingKeysWith: { first, _ in first })
                    binding.apply(
                        "Reset Graphic Properties",
                        binding.ops(
                            graphic: defaults, entries: entries, clips: clips(), schema: parsed?.raw))
                    return
                }
                let targets = clips()
                var keys = Set<String>()
                for clip in targets { keys.formUnion(clip.graphic?.props.keys.map { $0 } ?? []) }
                guard !keys.isEmpty else { return NSSound.beep() }
                binding.apply(
                    "Reset Graphic Properties",
                    [GraphicSchemaRows.op(
                        clips: targets,
                        props: Dictionary(uniqueKeysWithValues: keys.map { ($0, NSNull()) }),
                        schema: parsed?.raw)])
            },
            defaultExpanded: true,
            rows: rows)
    }

    // MARK: - Size

    /// Width and height, fanned out one op per clip in one apply, and Fit to
    /// Canvas: the canvas's size, centred at scale 1.
    func sizeSection() -> InspectorSection {
        let binding = self.binding
        func first() -> GraphicSnapshot? { binding.graphicClips.first?.graphic }
        func side(_ key: String, _ value: Double) -> [ReelOp] {
            binding.graphicClips.map {
                .setGraphicRaw(clips: [$0.id], patch: [key: Int(value.rounded())])
            }
        }
        return InspectorSection(
            id: "graphic.size", title: "Size",
            summary: { first().map { "\($0.width) × \($0.height)" } },
            defaultExpanded: false,
            rows: [
                inspectorValueRow(
                    "Width", binding, name: "Graphic Size", unit: " px", min: 1,
                    max: Double(GraphicLibrary.maxSide), slider: false,
                    width: InspectorMetrics.wideFieldWidth,
                    read: { Double(first()?.width ?? 0) }, ops: { side("width", $0) },
                    mixed: { binding.mixed(binding.graphicClips) { $0.graphic?.width } },
                    resets: false),
                inspectorValueRow(
                    "Height", binding, name: "Graphic Size", unit: " px", min: 1,
                    max: Double(GraphicLibrary.maxSide), slider: false,
                    width: InspectorMetrics.wideFieldWidth,
                    read: { Double(first()?.height ?? 0) }, ops: { side("height", $0) },
                    mixed: { binding.mixed(binding.graphicClips) { $0.graphic?.height } },
                    resets: false),
                inspectorButtonRow([
                    inspectorButton(
                        "Fit to Canvas", binding, name: "Fit Graphic to Canvas",
                        ops: { Self.fitToCanvasOps(clips: binding.graphicClips, canvas: binding.canvas) }),
                ]),
            ])
    }

    /// Per clip: the canvas's size, then the layer centred at scale 1.
    static func fitToCanvasOps(clips: [ClipSnapshot], canvas: CanvasSnapshot) -> [ReelOp] {
        clips.flatMap { clip -> [ReelOp] in
            [
                .setGraphicRaw(
                    clips: [clip.id], patch: ["width": canvas.width, "height": canvas.height]),
                .setVideo(clips: [clip.id], patch: VideoPatch(x: 0, y: 0, scale: 1)),
            ]
        }
    }

    // MARK: - Timeline

    /// The graphic's own timeline (G-9): In, read-only — the point
    /// `trim_start`, `roll` and `split` move — and Length, typed, which pins
    /// it; Follow Clip gives it back to the clip (`null`, which ends it at
    /// `in + duration`, G-9·c).
    ///
    /// Binds by clip ID and reads fresh through it, `timingSection`'s rule.
    func timelineSection(_ id: UInt32) -> InspectorSection {
        let binding = self.binding
        func clip() -> ClipSnapshot? { binding.snapshot.clip(id) }
        func fps() -> Fps { binding.canvas.fps }
        func frames() -> Bool { binding.canvas.timecodeFrames }
        func length() -> Ticks {
            guard let clip = clip() else { return 0 }
            return clip.graphicEffectiveLength ?? clip.duration
        }
        let field = InspectorTimecodeField(
            read: length,
            write: { value in
                binding.apply("Graphic Length", [.setGraphicRaw(clips: [id], patch: ["length": value])])
            },
            fps: fps, frames: frames,
            onEdit: { binding.edited() })
        field.toolTip = "How long the graphic's own timeline runs — typing pins it"
        return InspectorSection(
            id: "graphic.timeline", title: "Timeline",
            summary: { ReelTime.format(length(), fps: fps(), frames: frames()) },
            defaultExpanded: false,
            rows: [
                inspectorRow("In", [inspectorReadout {
                    ReelTime.format(clip()?.graphic?.sourceIn ?? 0, fps: fps(), frames: frames())
                }]),
                inspectorRow("Length", [field]),
                inspectorCheckRow(
                    "Follow Clip", binding, name: "Graphic Follow Clip",
                    read: { clip()?.graphic.map { $0.length == nil } ?? true },
                    ops: { on in
                        [.setGraphicRaw(
                            clips: [id], patch: ["length": on ? NSNull() : length() as Any])]
                    },
                    resets: false),
            ])
    }
}

// app/Sources/GraphicSchemaRows.swift — a graphic module's schema as the
// Graphic sub-tab's Properties rows (road map 10 §5j, G5a): the schema read
// in the MODULE's key order, one row per entry built with the inspector's
// existing builders, the stored keys the schema no longer has (G-4's
// leniency, made visible), and the two conversions a colour needs at the
// well's edge (G-12: a prop's colour is a CSS string, the well's is `RGBA`).
//
// **No state of its own.** Every function here is a function of its
// arguments, so a probe can drive each one without a window.
//
// **Where a write goes** (spec §11 G-34 (l)): with no action selected every
// row writes `set_graphic` to the clip; with one selected, a row reads the
// action's END state (`InspectorBinding.graphicProps`) and writes it — one
// `set_action_end` naming `graphic.props.<key>` with the module's schema —
// through `InspectorBinding.ops(graphic:…)`, an asset's included, its "no
// image" written as `""` there (G-42, `endValues`); only a prop its module
// marks `animate: false` (G-41) is still the clip's.
//
// **A value equal to the schema's default is written as `null`** to the
// clip (spec §11 G-15): the key leaves the stored props and the module
// draws its own default, which is exactly what Reset writes too. An end
// takes the value itself, since a `null` there removes (G-34 (j)). A colour is "equal" by
// its parsed channels, and a colour DEFAULT is read through the core's own
// G-12 (`ReelColor.normalise`, spec §11 G-25), so a name or `hsl()` default
// draws and matches as the colour it is; a default G-12 refuses does not
// compile (`model_graphic.rs`, the engine's `props.rs`).

import AppKit

enum GraphicSchemaRows {
    /// The swatch when a colour default is not a colour G-12 takes — which
    /// compile refuses, so only a schema no compile checked reaches it:
    /// transparent black.
    static let unparsedColor: RGBA = [0, 0, 0, 0]

    /// A JSON value from `JSONSerialization` as a prop value.
    static func value(_ any: Any?) -> GraphicPropValue {
        if let string = any as? String { return .string(string) }
        if let number = any as? NSNumber {
            return CFGetTypeID(number) == CFBooleanGetTypeID()
                ? .bool(number.boolValue) : .number(number.doubleValue)
        }
        return .null
    }

    /// A prop value as the JSON a patch carries.
    static func json(_ value: GraphicPropValue) -> Any {
        switch value {
        case .string(let string): return string
        case .number(let number): return number
        case .bool(let bool): return bool
        case .null: return NSNull()
        }
    }

    /// `#rgb`, `#rgba`, `#rrggbb` or `#rrggbbaa`, any case, as channels 0–1.
    static func rgba(css: String) -> RGBA? {
        let text = css.trimmingCharacters(in: .whitespaces)
        guard text.hasPrefix("#") else { return nil }
        let hex = Array(text.dropFirst())
        guard [3, 4, 6, 8].contains(hex.count), hex.allSatisfy(\.isHexDigit) else { return nil }
        let pairs: [String] = hex.count <= 4
            ? hex.map { String([$0, $0]) }
            : stride(from: 0, to: hex.count, by: 2).map { String(hex[$0..<$0 + 2]) }
        var channels = pairs.map { Double(UInt8($0, radix: 16) ?? 0) / 255 }
        if channels.count == 3 { channels.append(1) }
        return channels
    }

    /// `#rrggbb`, or `#rrggbbaa` when the alpha is below 1 — the core's own
    /// normalised form, lowercase.
    static func css(_ color: RGBA) -> String {
        let channels = (0..<4).map { index -> Int in
            let value = color.indices.contains(index) ? color[index] : 1
            return Int((Swift.min(Swift.max(value, 0), 1) * 255).rounded())
        }
        let rgb = channels[0..<3].map { String(format: "%02x", $0) }.joined()
        return "#" + rgb + (channels[3] == 255 ? "" : String(format: "%02x", channels[3]))
    }

    /// The colour a `color` entry's default draws as in the well.
    static func defaultColor(_ entry: GraphicSchemaEntry) -> RGBA {
        if case .string(let text) = entry.default, let hex = ReelColor.normalise(text),
           let color = rgba(css: hex) {
            return color
        }
        return unparsedColor
    }

    /// What a write sends for `value`: `null` when it equals the default,
    /// else the value itself.
    static func patchValue(_ value: GraphicPropValue, for entry: GraphicSchemaEntry) -> Any {
        if entry.type == "color" {
            if case .string(let text) = value, rgba(css: text) == defaultColor(entry) {
                return NSNull()
            }
        } else if value == entry.default {
            return NSNull()
        }
        return json(value)
    }

    /// A base write's props: each value through `patchValue` against its
    /// entry, and a key no entry declares as it is.
    static func patchProps(
        _ values: [String: GraphicPropValue], entries: [GraphicSchemaEntry]
    ) -> [String: Any] {
        var props: [String: Any] = [:]
        for (key, value) in values {
            if let entry = entries.first(where: { $0.key == key }) {
                props[key] = patchValue(value, for: entry)
            } else {
                props[key] = json(value)
            }
        }
        return props
    }

    /// The stored keys `schema` does not declare, sorted — all of them when
    /// there is no compiled schema.
    static func staleKeys(stored: [String: GraphicPropValue], schema: GraphicSchema?) -> [String] {
        let declared = Set(schema?.keys ?? [])
        return stored.keys.filter { !declared.contains($0) }.sorted()
    }

    /// The keys the selected action's END names that no row writes into it,
    /// sorted: each `schema` does not declare and each whose entry is not
    /// `animatable` (G-41 (c)); every key with no compiled schema. The
    /// undeclared keys are `staleKeys`' own.
    static func actionStaleKeys(end: [String: GraphicPropValue], schema: GraphicSchema?) -> [String] {
        let held = Set((schema?.entries ?? []).filter { !$0.animatable }.map(\.key))
        let declaredHeld = end.keys.filter { held.contains($0) }
        return (staleKeys(stored: end, schema: schema) + declaredHeld).sorted()
    }

    /// A number row's decimals: with a `step`, 2 below 1 and else 0; with
    /// none, 2 when the default, `min` or `max` has a fraction, else 0.
    static func decimals(for entry: GraphicSchemaEntry) -> Int {
        if let step = entry.step { return step < 1 ? 2 : 0 }
        var values = [entry.min, entry.max].compactMap { $0 }
        if case .number(let number) = entry.default { values.append(number) }
        return values.contains { $0 != $0.rounded() } ? 2 : 0
    }

    /// An end write's props: each value as it is, except an `asset` entry's `.null`, which is
    /// `.string("")` — "no image" in an end, where a `null` removes (spec §11 G-42).
    static func endValues(
        _ values: [String: GraphicPropValue], entries: [GraphicSchemaEntry]
    ) -> [String: GraphicPropValue] {
        var out: [String: GraphicPropValue] = [:]
        for (key, value) in values {
            guard let entry = entries.first(where: { $0.key == key }) else {
                out[key] = value
                continue
            }
            out[key] = entry.type == "asset" && value == .null ? .string("") : value
        }
        return out
    }

    /// An asset entry's popup names: the folder's `files`, then, sorted,
    /// every name a clip holds under `entry.key`, the selected action's
    /// `end` holds, and a string default, that `files` lacks. A `""` is no
    /// image ("None", G-42) and never a name. The rows and the pane's
    /// signature both call this.
    static func assetNames(
        for entry: GraphicSchemaEntry, files: [String], clips: [ClipSnapshot],
        end: [String: GraphicPropValue]
    ) -> [String] {
        var held = clips.compactMap { clip -> String? in
            if case .string(let text)? = clip.graphic?.props[entry.key], !text.isEmpty { return text }
            return nil
        }
        if case .string(let text)? = end[entry.key], !text.isEmpty { held.append(text) }
        if case .string(let text) = entry.default, !text.isEmpty { held.append(text) }
        return files + Set(held).subtracting(files).sorted()
    }

    /// `set_graphic {clips, patch: {props}, schema}` over `clips`.
    static func op(clips: [ClipSnapshot], props: [String: Any], schema: [String: Any]?) -> ReelOp {
        .setGraphicRaw(clips: clips.map(\.id), patch: ["props": props], schema: schema)
    }

    // MARK: - Rows

    /// One schema entry's row. Every `read` answers the default in the
    /// binding's `.defaults` mode, so the builders' derived Reset works, and
    /// otherwise the binding's mode's value (the selected action's end, its
    /// start, the playhead); every write is `InspectorBinding.ops(graphic:…)`
    /// over `clips()`.
    static func row(
        _ entry: GraphicSchemaEntry, _ binding: InspectorBinding,
        clips: @escaping () -> [ClipSnapshot], schema: [String: Any],
        assets: @escaping () -> [String]
    ) -> NSView {
        let key = entry.key, name = "Graphic " + entry.label
        func stored() -> GraphicPropValue? {
            clips().first.map { binding.graphicProps($0)[key] } ?? nil
        }
        func current() -> GraphicPropValue { stored() ?? entry.default }
        func ops(_ value: GraphicPropValue) -> [ReelOp] {
            binding.ops(graphic: value, for: entry, clips: clips(), schema: schema)
        }
        let mixed = { binding.mixed(clips()) { binding.graphicProps($0)[key] } }
        let view: NSView
        switch entry.type {
        case "number":
            let fallback: Double = {
                if case .number(let number) = entry.default { return number }
                return 0
            }()
            let bounded = entry.min != nil && entry.max != nil
            view = inspectorValueRow(
                entry.label, binding, name: name,
                decimals: decimals(for: entry),
                min: entry.min ?? -1e9, max: entry.max ?? 1e9, slider: bounded,
                read: {
                    if case .number(let number) = current() { return number }
                    return fallback
                },
                ops: { ops(.number($0)) }, mixed: mixed)
        case "boolean":
            view = inspectorCheckRow(
                entry.label, binding, name: name,
                read: {
                    if case .bool(let bool) = current() { return bool }
                    if case .bool(let bool) = entry.default { return bool }
                    return false
                },
                ops: { ops(.bool($0)) }, mixed: mixed)
        case "color":
            view = inspectorColorRow(
                entry.label, binding, name: name,
                read: {
                    if case .string(let text)? = stored(), let color = rgba(css: text) {
                        return color
                    }
                    return defaultColor(entry)
                },
                ops: { ops(.string(css($0))) }, mixed: mixed)
        case "enum":
            let options = entry.options
            view = inspectorPopupRow(
                entry.label, binding, name: name, items: options,
                read: {
                    if case .string(let text) = current(), let index = options.firstIndex(of: text) {
                        return index
                    }
                    if case .string(let text) = entry.default,
                       let index = options.firstIndex(of: text)
                    {
                        return index
                    }
                    return 0
                },
                ops: { index in options.indices.contains(index) ? ops(.string(options[index])) : [] },
                mixed: mixed)
        case "asset":
            view = assetRow(entry, binding, name: name, clips: clips, assets: assets,
                            current: current, ops: ops, mixed: mixed)
        case "string":
            view = stringRow(entry, binding, name: name, current: current, ops: ops, mixed: mixed)
        default:
            view = inspectorRow(
                entry.label, [inspectorReadout { "type \"\(entry.type)\" is not supported" }])
        }
        view.toolTip = entry.help
        return view
    }

    /// The asset popup: "None" first on every asset row (G-42 (d)), the
    /// folder's files, then any name a clip or the selected action's end
    /// holds (or the default names) that the folder does not. A `""`, a
    /// `null` or an unknown value reads as "None". "None" writes `null` at
    /// the base when the default is `null` and `""` when it is a string; an
    /// end takes `""` either way (`endValues`).
    private static func assetRow(
        _ entry: GraphicSchemaEntry, _ binding: InspectorBinding, name: String,
        clips: @escaping () -> [ClipSnapshot], assets: @escaping () -> [String],
        current: @escaping () -> GraphicPropValue,
        ops: @escaping (GraphicPropValue) -> [ReelOp], mixed: @escaping () -> Bool
    ) -> NSView {
        let names = assetNames(
            for: entry, files: assets(), clips: clips(),
            end: binding.selectedAction?.end.graphic?.props ?? [:])
        let items = ["None"] + names
        let offset = 1
        return inspectorPopupRow(
            entry.label, binding, name: name, items: items,
            read: {
                if case .string(let text) = current(), let index = names.firstIndex(of: text) {
                    return index + offset
                }
                return 0
            },
            ops: { index in
                if index == 0 { return ops(entry.default == .null ? .null : .string("")) }
                let at = index - offset
                return names.indices.contains(at) ? ops(.string(names[at])) : []
            },
            mixed: mixed)
    }

    /// A string entry: a one-line field, or a text area when `multiline`.
    /// `OptionFieldControl` is numeric, so the row is assembled here with an
    /// explicit default rather than through `inspectorValueRow`.
    private static func stringRow(
        _ entry: GraphicSchemaEntry, _ binding: InspectorBinding, name: String,
        current: @escaping () -> GraphicPropValue,
        ops: @escaping (GraphicPropValue) -> [ReelOp], mixed: @escaping () -> Bool
    ) -> NSView {
        let read: () -> String = {
            if case .string(let text) = current() { return text }
            return ""
        }
        let write: (String) -> [ReelOp] = { ops(.string($0)) }
        let control: NSView = entry.multiline
            ? InspectorTextArea(
                read: read, write: { [weak binding] in binding?.apply(name, write($0)) },
                enabled: { true }, onEdit: { [weak binding] in binding?.edited() })
            : InspectorNameField(
                read: read, write: { [weak binding] in binding?.apply(name, write($0)) },
                enabled: { true }, onEdit: { [weak binding] in binding?.edited() })
        // Either control takes the row's width (`inspectorRow`, spec §11 G-48).
        return inspectorRow(
            entry.label, [control], mixed: mixed, binding: binding, writes: write(read()),
            discrete: true, default: .derived(binding, name: name, read: read, ops: write))
    }

    /// A stored key the schema no longer declares: the key dimmed, its value,
    /// and ⌫, which writes `{key: null}` — a null always removes (G-4).
    static func staleRow(
        key: String, value: GraphicPropValue, _ binding: InspectorBinding,
        clips: @escaping () -> [ClipSnapshot]
    ) -> NSView {
        let (label, readout) = staleLabels(key: key, value: value)
        let remove = OptionButtonControl(
            title: "⌫",
            action: { [weak binding] in
                let targets = clips()
                binding?.apply(
                    "Remove Graphic Property",
                    targets.isEmpty ? [] : [op(clips: targets, props: [key: NSNull()], schema: nil)])
            },
            enabled: { true }, onEdit: {})
        remove.toolTip = "The module no longer declares \(key) — remove the stored value"
        return inspectorRow(nil, [label, readout, remove])
    }

    /// A key the selected action's END names that the schema no longer
    /// declares (G-34 (l), O2), or `declared` but not `animatable` (G-41 (c)):
    /// its row beside the clip's own, marked as the end's, with ⌫ taking it
    /// out of the end — `clearOps`, no schema.
    static func actionStaleRow(
        key: String, value: GraphicPropValue, declared: Bool, _ binding: InspectorBinding
    ) -> NSView {
        let (label, readout) = staleLabels(key: key, value: value)
        let ops = binding.clearOps(["graphic.props." + key])
        let remove = OptionButtonControl(
            title: "⌫",
            action: { [weak binding] in binding?.apply("Remove from Action", ops) },
            enabled: { true }, onEdit: {})
        let number = binding.selectedActionNumber.map { String($0) } ?? ""
        remove.toolTip = declared
            ? "The module does not let \(key) be animated — remove it from action \(number)"
            : "The module no longer declares \(key) — remove it from action \(number)"
        return inspectorRow(nil, [label, readout, remove], binding: binding, writes: ops)
    }

    /// A stale row's key, dimmed, and its value.
    private static func staleLabels(
        key: String, value: GraphicPropValue
    ) -> (InspectorRowLabel, NSView) {
        let label = InspectorRowLabel(key)
        label.textColor = DS.textFaint
        label.translatesAutoresizingMaskIntoConstraints = false
        label.widthAnchor.constraint(equalToConstant: InspectorMetrics.labelWidth).isActive = true
        let shown: String
        switch value {
        case .string(let text): shown = "\"\(text)\""
        case .number(let number): shown = String(format: "%g", number)
        case .bool(let bool): shown = bool ? "true" : "false"
        case .null: shown = "null"
        }
        let readout = inspectorReadout(width: 110) { shown }
        readout.alphaValue = 0.55
        return (label, readout)
    }
}
