509	extension ProjectDocument {
510	    /// Plans `contents` against this project and copies it in; the plan it carried out.
511	    func importGraphicPackage(_ contents: GraphicPackageContents) throws -> GraphicImportPlan {
512	        let plan = try GraphicImportPlan.make(contents, document: self)
513	        guard let store = graphicStore else {
514	            throw ReelCoreError(message: Self.noGraphicsFolderSentence)
515	        }
516	        try plan.apply(to: store)
517	        return plan
518	    }
