235	// app/Sources/GraphicPackageImport.swift — a `.fjgraphic` copied into a
236	// project's `graphics/` (spec §11 G-47): what the package holds, where each
237	// file goes, the copy, and what it answers. No UI: the sheet
238	// (`GraphicImportSheetController.swift`) and `import_graphic`
239	// (`AgentServer+GraphicImports.swift`) both call these bodies, so the two
240	// doors refuse in the same sentences.
241	//
242	// **The checks** (G-47 (c)) are the core's first — `ReelGraphicPackage.read`,
243	// the archive and its manifest — then the app's: a font must load in a
244	// throwaway library, as `importFont` does, and an asset must be a name
245	// `asset(name)` can use. Every refusal is "<file name> cannot be imported:
246	// <sentence>", and none writes anything.
247	//
248	// **The plan** (G-47 (d)) puts each file under the manifest's name: written
249	// when the name is free, reused when the file there holds the same bytes;
250	// otherwise a module or a font takes `-2`, `-3`, … and an asset refuses the
251	// import, because the module reaches it by name. A name is matched exactly:
252	// one that differs only in case is another file, and is never free.
253	//
254	// **The copy** (G-47 (e)) writes the fonts, then the assets, with
255	// `landNew` (never replacing), then the module with `write(name:bytes:)`; a
256	// throw removes every file it wrote, rescans and rethrows. One `rescan()` at
257	// the end, from the caller's handler or command — never from a
258	// `.graphicsDidChange` observer. Not undoable and never dirty (G-3).
259	
260	import Foundation
261	
262	/// One font or asset of a package, under the manifest's `name`.
263	struct GraphicPackageFile {
264	    let name: String
265	    let bytes: Data
266	}
267	
268	/// A package read and checked, ready to plan.
269	struct GraphicPackageContents {
270	    let module: String
271	    let title: String
272	    let category: String
273	    let description: String?
274	    let appVersion: String
275	    let source: Data
276	    let fonts: [GraphicPackageFile]
277	    let assets: [GraphicPackageFile]
278	
279	    /// Reads the file at `url` and checks it, the core's checks then the app's.
280	    static func read(at url: URL) throws -> GraphicPackageContents {
281	        let refuse = { (sentence: String) in
282	            ReelCoreError(message: "\(url.lastPathComponent) cannot be imported: \(sentence)")
283	        }
284	        let values = try? url.resourceValues(forKeys: [.isRegularFileKey, .fileSizeKey])
285	        guard values?.isRegularFile == true else { throw refuse("it is not a file") }
286	        let size = values?.fileSize ?? 0
287	        guard size > 0 else { throw refuse("it is empty (0 bytes)") }
288	        guard UInt64(size) <= UInt64(UInt32.max) else {
289	            throw refuse("it is \(size) bytes, more than a .fjgraphic holds (\(UInt32.max))")
290	        }
291	        let data: Data
292	        do {
293	            data = try Data(contentsOf: url)
294	        } catch {
295	            throw refuse("it could not be read: \(error.localizedDescription)")
296	        }
297	        let answer: String
298	        do {
299	            answer = try ReelGraphicPackage.read(data)
300	        } catch let error as ReelCoreError {
301	            throw refuse(error.message)
302	        }
303	        guard let manifest = (try? JSONSerialization.jsonObject(with: Data(answer.utf8)))
304	            as? [String: Any], let files = manifest["files"] as? [[String: Any]],
305	            let first = files.first
306	        else { throw refuse("the core's answer could not be read") }
307	        func bytes(_ file: [String: Any]) -> Data {
308	            let offset = file["offset"] as? Int ?? 0, length = file["size"] as? Int ?? 0
309	            return data.subdata(in: offset..<(offset + length))
310	        }
311	        var fonts: [GraphicPackageFile] = [], assets: [GraphicPackageFile] = []
312	        for file in files.dropFirst() {
313	            let entry = GraphicPackageFile(name: file["name"] as? String ?? "", bytes: bytes(file))
314	            let path = file["path"] as? String ?? ""
315	            if path.hasPrefix(GraphicStore.fontsFolderName + "/") {
316	                fonts.append(entry)
317	            } else {
318	                assets.append(entry)
319	            }
320	        }
321	        for font in fonts {
322	            let ext = (font.name as NSString).pathExtension.lowercased()
323	            guard GraphicStore.fontExtensions.contains(ext) else {
324	                throw refuse("the font \"\(font.name)\" is not a .ttf or .otf file")
325	            }
326	            do {
327	                try GraphicLibrary().addFont(font.bytes)
328	            } catch let error as ReelCoreError {
329	                throw refuse("the font \"\(font.name)\": \(error.message)")
330	            }
331	        }
332	        for asset in assets {
333	            let ext = (asset.name as NSString).pathExtension.lowercased()
334	            guard GraphicStore.assetExtensions.contains(ext) else {
335	                throw refuse(
336	                    "the picture \"\(asset.name)\" is not a \(GraphicStore.assetKinds) file")
337	            }
338	            guard GraphicAssetName.isLegal(asset.name) else {
339	                throw refuse("the picture \"\(asset.name)\" \(GraphicAssetName.rule)")
340	            }
341	            guard !asset.bytes.isEmpty else {
342	                throw refuse("the picture \"\(asset.name)\" is empty (0 bytes)")
343	            }
344	        }
345	        return GraphicPackageContents(
346	            module: manifest["module"] as? String ?? "", title: manifest["title"] as? String ?? "",
347	            category: manifest["category"] as? String ?? "",
348	            description: manifest["description"] as? String,
349	            appVersion: manifest["app_version"] as? String ?? "", source: bytes(first),
350	            fonts: fonts, assets: assets)
351	    }
352	}
353	
354	/// What an import does with one file.
355	enum GraphicImportAction: String {
356	    case written, reused
357	}
358	
359	/// One file's place: `name` the manifest's, `target` the name on disk.
360	struct GraphicImportPlacement {
361	    let name: String
362	    let target: String
363	    let action: GraphicImportAction
364	}
365	
366	/// Where every file of a package goes in one project, and the copy.
367	struct GraphicImportPlan {
368	    let contents: GraphicPackageContents
369	    let module: GraphicImportPlacement
370	    let fonts: [GraphicImportPlacement]
371	    let assets: [GraphicImportPlacement]
372	
373	    /// G-47 (d) over the store's scan and the disk. Throws, writing nothing, for an asset
374	    /// whose name holds a different picture, or with no store.
375	    static func make(_ contents: GraphicPackageContents, document: ProjectDocument) throws
376	        -> GraphicImportPlan
377	    {
378	        guard let store = document.graphicStore else {
379	            throw ReelCoreError(message: ProjectDocument.noGraphicsFolderSentence)
380	        }
381	        let folder = store.folderURL
382	        let free = { (name: String) in
383	            !store.holdsModule(named: name) && document.graphicClips(named: name).isEmpty
384	        }
385	        let module: GraphicImportPlacement
386	        let held = try? Data(contentsOf: folder.appendingPathComponent(contents.module + ".js"))
387	        if free(contents.module) {
388	            module = .init(name: contents.module, target: contents.module, action: .written)
389	        } else if held == contents.source {
390	            module = .init(name: contents.module, target: contents.module, action: .reused)
391	        } else {
392	            let root = String(String.UnicodeScalarView(contents.module.unicodeScalars.prefix(60)))
393	            var n = 2
394	            while !free("\(root)-\(n)") { n += 1 }
395	            module = .init(name: contents.module, target: "\(root)-\(n)", action: .written)
396	        }
397	        var fonts = Names(folder.appendingPathComponent(GraphicStore.fontsFolderName))
398	        let fontPlaces = contents.fonts.map { font -> GraphicImportPlacement in
399	            var target = font.name
400	            var n = 2
401	            while true {
402	                if let action = fonts.place(target, font.bytes) {
403	                    return .init(name: font.name, target: target, action: action)
404	                }
405	                target = GraphicAssetName.withSuffix(font.name, n)
406	                n += 1
407	            }
408	        }
409	        var assets = Names(folder.appendingPathComponent(GraphicStore.assetsFolderName))
410	        let assetPlaces = try contents.assets.map { asset -> GraphicImportPlacement in
411	            guard let action = assets.place(asset.name, asset.bytes) else {
412	                throw ReelCoreError(
413	                    message: "graphics/assets/\(asset.name) already holds a different picture, "
414	                        + "and this graphic reaches its own by asset(\"\(asset.name)\"), so it "
415	                        + "cannot be renamed; rename or remove the project's file and import "
416	                        + "again")
417	            }
418	            return .init(name: asset.name, target: asset.name, action: action)
419	        }
420	        return GraphicImportPlan(
421	            contents: contents, module: module, fonts: fontPlaces, assets: assetPlaces)
422	    }
423	
424	    /// One folder's names, as the disk holds them and as this plan claims them.
425	    private struct Names {
426	        let folder: URL
427	        var taken: [String]
428	
429	        init(_ folder: URL) {
430	            self.folder = folder
431	            taken = (try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? []
432	        }
433	
434	        /// `.written` when `name` is free (and claims it), `.reused` when a file of exactly
435	        /// that name holds `bytes`, nil otherwise — a name that differs only in case is taken.
436	        mutating func place(_ name: String, _ bytes: Data) -> GraphicImportAction? {
437	            let url = folder.appendingPathComponent(name)
438	            if taken.contains(name) {
439	                return (try? Data(contentsOf: url)) == bytes ? .reused : nil
440	            }
441	            let folded = name.lowercased()
442	            guard !taken.contains(where: { $0.lowercased() == folded }),
443	                !FileManager.default.fileExists(atPath: url.path)
444	            else { return nil }
445	            taken.append(name)
446	            return .written
447	        }
448	    }
449	
450	    /// The copy: fonts, assets, then the module, none replacing a file; a throw removes what
451	    /// it wrote and rescans. One `rescan()` at the end. Main.
452	    func apply(to store: GraphicStore) throws {
453	        var written: [URL] = []
454	        var current = ""
455	        do {
456	            try store.ensureFolder()
457	            for (folder, places, files) in [
458	                (GraphicStore.fontsFolderName, fonts, contents.fonts),
459	                (GraphicStore.assetsFolderName, assets, contents.assets),
460	            ] {
461	                for (place, file) in zip(places, files) where place.action == .written {
462	                    current = "\(folder)/\(place.target)"
463	                    written.append(try store.landNew(file.bytes, into: folder, as: place.target))
464	                }
465	            }
466	            if module.action == .written {
467	                current = "\(module.target).js"
468	                try store.write(name: module.target, bytes: contents.source)
469	            }
470	        } catch {
471	            for url in written { try? FileManager.default.removeItem(at: url) }
472	            store.rescan()
473	            let why = (error as? ReelCoreError)?.message ?? error.localizedDescription
474	            throw ReelCoreError(message: "graphics/\(current) could not be written: \(why)")
475	        }
476	        store.rescan()
477	    }
478	
479	    /// `Imported <title> as <module>. Added: …. Already here: ….`
480	    var sentence: String {
481	        let all = [("\(module.target).js", module.action)]
482	            + fonts.map { ("\(GraphicStore.fontsFolderName)/\($0.target)", $0.action) }
483	            + assets.map { ("\(GraphicStore.assetsFolderName)/\($0.target)", $0.action) }
484	        var text = "Imported \(contents.title) as \(module.target)."
485	        for (label, action) in [("Added", GraphicImportAction.written), ("Already here", .reused)] {
486	            let names = all.filter { $0.1 == action }.map(\.0)
487	            if !names.isEmpty { text += " \(label): " + names.joined(separator: ", ") + "." }
488	        }
489	        return text
490	    }
491	
492	    /// `import_graphic`'s answer (spec §11 G-47 (i)).
493	    var reply: [String: Any] {
494	        var out: [String: Any] = [
495	            "name": module.target, "title": contents.title, "module": module.action.rawValue,
496	            "fonts": fonts.map { font -> [String: Any] in
497	                var row: [String: Any] = ["name": font.target, "action": font.action.rawValue]
498	                if font.target != font.name { row["renamed_from"] = font.name }
499	                return row
500	            },
501	            "assets": assets.map { ["name": $0.target, "action": $0.action.rawValue] },
502	            "note": AgentServer.notUndoableNote,
503	        ]
504	        if module.target != module.name { out["renamed_from"] = module.name }
505	        return out
506	    }
507	}
