520	// app/Sources/GraphicPackage.swift — the Graphic dialog's Export… and
521	// `export_graphic` (spec §11 G-46): one graphic written as a `.fjgraphic`
522	// package holding its module and only the project fonts and assets the
523	// engine saw it use.
524	//
525	// **A job is built on main and written off it.** `GraphicPackageJob.project`
526	// and `.template` read the document on main: the module's bytes, its title,
527	// category and description (`GraphicCatalog`), its size and length
528	// (`AgentServer.metaWhole`, as `render_graphic` reads them), and a FRESH
529	// library (`GraphicStore.makeIndexedLibrary()`; a template's holds the
530	// bundled faces alone). `write(to:)` runs QuickJS, so it runs only on the
531	// sheet's 8 MiB `Thread` or the agent's server thread — never main, never GCD.
532	//
533	// **The usage rule** (G-46 (b)): the module is compiled against that library
534	// and drawn — every frame up to `maxFrames` with its default props, else
535	// `maxFrames` evenly spaced, each `svg` then `rasterize` — and then each
536	// variant (an `enum` option other than the default, a boolean's opposite, in
537	// schema order, at most `maxVariants`) over `variantFrames` evenly spaced
538	// frames, every other prop at its default. The library's `usage()` is then
539	// every project font blob and asset to pack; a bundled face never is. A
540	// frame that throws is skipped and counted.
541	//
542	// **The file** is the core's (`ReelGraphicPackage.write`): written as
543	// `.<file>.partial` beside the destination and renamed over it, so an
544	// existing file is replaced whole; any throw removes the partial file.
545	
546	import Foundation
547	import UniformTypeIdentifiers
548	
549	enum GraphicPackage {
550	    static let fileExtension = "fjgraphic", typeIdentifier = "com.kgalligan.framejob-graphic"
551	    static let maxFrames = 900, variantFrames = 30, maxVariants = 32
552	
553	    /// The exported type (`project.yml`), else data by its extension (spec §11 G-47 (g)).
554	    static var contentType: UTType {
555	        UTType(typeIdentifier)
556	            ?? UTType(filenameExtension: fileExtension, conformingTo: .data) ?? .data
557	    }
558	
559	    /// The manifest's `app_version`: the bundle's `CFBundleShortVersionString`, else "".
560	    static var appVersion: String {
561	        Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? ""
562	    }
563	
564	    /// Every frame of `length` when there are at most `cap`, else `cap` frames evenly spaced
565	    /// from the first to the last.
566	    static func sampledFrames(length: Int, cap: Int) -> [Int] {
567	        guard length > cap else { return Array(0..<max(length, 0)) }
568	        guard cap > 1 else { return cap == 1 ? [0] : [] }
569	        return (0..<cap).map { i in
570	            Int((Double(i) * Double(length - 1) / Double(cap - 1)).rounded())
571	        }
572	    }
573	
574	    /// The props of each variant G-46 (b) draws: one per `enum` option other than its
575	    /// default and one per boolean's opposite, in schema order, at most `maxVariants`.
576	    static func variants(_ schema: GraphicSchema) -> [[String: Any]] {
577	        var out: [[String: Any]] = []
578	        for entry in schema.entries {
579	            switch (entry.type, entry.default) {
580	            case ("enum", let value):
581	                let current: String? = { if case .string(let s) = value { return s }; return nil }()
582	                for option in entry.options where option != current {
583	                    out.append([entry.key: option])
584	                }
585	            case ("boolean", .bool(let flag)):
586	                out.append([entry.key: !flag])
587	            default:
588	                continue
589	            }
590	        }
591	        return Array(out.prefix(maxVariants))
592	    }
593	}
594	
595	/// What one export wrote.
596	struct GraphicPackageResult {
597	    let url: URL
598	    /// The manifest's in-package paths, in order; `manifest.json` itself is not among them.
599	    let files: [String]
600	    /// Every frame drawn (the defaults' and the variants'), and how many of them threw.
601	    let frames: Int
602	    let failedFrames: Int
603	}
604	
605	/// One graphic, read off the document on main, ready to be written off it.
606	struct GraphicPackageJob {
607	    let name: String
608	    /// What a compile failure names: `graphics/<name>.js` or `the template "<name>"`.
609	    let label: String
610	    let title: String
611	    let category: String
612	    let description: String?
613	    let source: Data
614	    let library: GraphicLibrary
615	    /// The library's font blobs: the project file each came from, nil for a bundled face.
616	    let fonts: [GraphicFile?]
617	    let assets: [GraphicFile]
618	    let width: Int
619	    let height: Int
620	    let length: Int
621	    let fps: Fps
622	    let canvas: CanvasSnapshot
623	    let appVersion: String
624	
625	    /// A This Project module, read on main. Throws the store's sentence when the folder does
626	    /// not hold it.
627	    static func project(named name: String, document: ProjectDocument) throws -> GraphicPackageJob {
628	        guard let store = document.graphicStore else {
629	            throw ReelCoreError(message: ProjectDocument.noGraphicsFolderSentence)
630	        }
631	        let indexed = try store.makeIndexedLibrary()
632	        guard let file = indexed.scan.modules[name] else {
633	            throw ReelCoreError(message: store.noModuleSentence(name))
634	        }
635	        var meta: [String: Any] = [:]
636	        if case .compiled(_, _, let described, _)? = GraphicRegistry.shared.entry(
637	            named: name, for: document.recipeKey)
638	        {
639	            meta = described
640	        }
641	        return try make(
642	            name: name, label: "graphics/\(name).js", meta: meta, source: file.bytes,
643	            library: indexed.library, fonts: indexed.fonts, assets: indexed.scan.assets,
644	            document: document)
645	    }
646	
647	    /// A bundled template, read on main, with a library of the bundled faces alone.
648	    static func template(
649	        _ entry: GraphicTemplateLibrary.Entry, document: ProjectDocument
650	    ) throws -> GraphicPackageJob {
651	        let name = entry.template.name
652	        let source: Data
653	        do {
654	            source = try Data(contentsOf: entry.template.url)
655	        } catch {
656	            throw ReelCoreError(
657	                message: "\(entry.template.url.path) could not be read: "
658	                    + error.localizedDescription)
659	        }
660	        let library = GraphicLibrary()
661	        var fonts: [GraphicFile?] = []
662	        for url in GraphicStore.bundledFontURLs(in: ProjectDocument.bundledFontsDirectory) {
663	            try library.addFont(Data(contentsOf: url))
664	            fonts.append(nil)
665	        }
